import sys
import random

def print_seed(seed):
    if not seed:
        seed = random.randint(1, 1000000)
    print(seed)

def main():
    if len(sys.argv) != 2:
        print("Usage: python seed.py <seed_file>")
        sys.exit(1)

    seed_file = sys.argv[1]
    seed = int(seed_file)
    print_seed(seed)

if __name__ == "__main__":
    main()
